    .replace(/```/g, '')
    .trim();

  // 3. Recortar solo el bloque JSON real
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error('No se encontró JSON válido en la respuesta');
  }
  cleaned = cleaned.substring(firstBrace, lastBrace + 1);

  // 4. Reparaciones típicas de GPT

  // Comas duplicadas
  cleaned = cleaned
    .replace(/\}\s*,\s*,/g, '},')
    .replace(/\]\s*,\s*,/g, '],')
    .replace(/,(\s*[\]}])/g, '$1');

  // 👉 COMAS FALTANTES ENTRE PROPIEDADES (la causa real de tu error)
  cleaned = cleaned.replace(
    /"\s*\n\s*"(?![:,}\]])/g,
    '",\n"'
  );

  // 👉 Coma faltante después de strings largos antes de siguiente key
  cleaned = cleaned.replace(
    /"([^"]+)"\s*\n\s*"([a-zA-Z0-9_]+)"\s*:/g,
    '"$1",\n"$2":'
  );

  // 5. Parsear seguro
  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    console.error('=== JSON QUE FALLÓ ===');
    console.error(cleaned.substring(0, 1500));
    throw new Error(`Error parseando JSON de la IA: ${error.message}`);
  }
}

