      c4: parseInt(criterios.c4) || 0,
      c5: parseInt(criterios.c5) || 0,
      c6: parseInt(criterios.c6) || 0,
      justificacion: r.justificacion || 'Sin justificación',
      numero_ejecucion: $('Start').first().json.numero_ejecucion || 'unknown'
    }
  };
});

// NODO CODE - Genera payload para OpenRouter (formato exacto documentación)
const input = $input.first().json;

// Obtener el prompt del campo correspondiente
const userPrompt = input.chatInput || input.userPrompt || input.prompt;

if (!userPrompt) {
  throw new Error('No se encontró el prompt en chatInput, userPrompt o prompt');
}

// Construir payload EXACTAMENTE como muestra la documentación de OpenRouter
const payload = {
  model: "deepseek/deepseek-r1-0528",  // Formato: "proveedor/modelo"
  messages: [
    {
      role: "user",
      content: userPrompt  // SOLO role: user, NADA de system
    }
  ],
  stream: false  // false para respuestas completas
};

// Devolver el payload
return [
  {
    json: {
      // Para RAW JSON en HTTP Request
      openrouter_payload: JSON.stringify(payload),

      // Para JSON estructurado en HTTP Request
      openrouter_payload_parsed: payload,

      // Metadata (se pasa igual)
      numero_ejecucion: input.numero_ejecucion || input.execution_id,
      batchNumber: input.batchNumber
    }
  }
];
